# Patch v91 contextual wake listener to use v107 reliable matcher without rewriting the whole listener.
wake_path = Path("seed_wake_context_v91.py")
if wake_path.exists():
    txt = wake_path.read_text(errors="ignore")
    marker = "# v107 reliable wake override"
    block = """
# v107 reliable wake override
try:
    from seed_wake_reliability_v107 import match_wake_reliable as _seed_v107_match_wake_reliable

    def match_wake(text):
        return _seed_v107_match_wake_reliable(text)
except Exception:
    pass

"""
    if marker not in txt:
        idx = txt.find('if __name__ == "__main__":')
        if idx >= 0:
            txt = txt[:idx] + block + txt[idx:]
        else:
            txt += "\n" + block
        wake_path.write_text(txt)
        print("Patched seed_wake_context_v91.py with v107 reliable wake override")
    else:
        print("seed_wake_context_v91.py already has v107 reliable wake override")
else:
    print("Warning: seed_wake_context_v91.py not found; v107 wake matcher module still installed")

